-- Insert roadmap skill nodes from D:/RoadmapDataTemplate.csv
-- Run this in PostgreSQL/Supabase SQL editor.
BEGIN;

CREATE TEMP TABLE roadmap_skill_node_seed (
    row_no INT PRIMARY KEY,
    node_id UUID NOT NULL DEFAULT gen_random_uuid(),
    career_name VARCHAR(255) NOT NULL,
    subtree_name VARCHAR(255),
    connect_to_name VARCHAR(255),
    child_node_of_name VARCHAR(255),
    node_name VARCHAR(255) NOT NULL,
    level INT,
    description TEXT,
    resource JSONB
) ON COMMIT DROP;


-- Make sure career rows exist before inserting nodes.
SELECT DISTINCT seed.career_name
FROM roadmap_skill_node_seed seed
WHERE NOT EXISTS (
    SELECT 1 FROM career_roles career
    WHERE career.career_name = seed.career_name
);

-- Insert nodes first. Self-references are resolved in the next UPDATE.
SELECT
    seed.node_id,
    career.career_id,
    seed.subtree_name,
    seed.node_name,
    seed.level,
    seed.description,
    seed.resource
FROM roadmap_skill_node_seed seed
JOIN career_roles career ON career.career_name = seed.career_name
WHERE NOT EXISTS (
    SELECT 1
    FROM skill_nodes existing
    WHERE existing.career_id = career.career_id
      AND existing.node_name = seed.node_name
      AND COALESCE(existing.subtree_name, '') = COALESCE(seed.subtree_name, '')
      AND COALESCE(existing.level, -1) = COALESCE(seed.level, -1)
);

-- Resolve connect_to and child_node_of by node name inside the same roadmap/career.
-- If duplicate node names exist, the first row in the CSV is used as the referenced node.
WITH inserted_nodes AS (
    SELECT seed.row_no, seed.node_id, seed.career_name, seed.connect_to_name, seed.child_node_of_name
    FROM roadmap_skill_node_seed seed
), reference_nodes AS (
    SELECT DISTINCT ON (seed.career_name, seed.node_name)
        seed.career_name,
        seed.node_name,
        seed.node_id
    FROM roadmap_skill_node_seed seed
    ORDER BY seed.career_name, seed.node_name, seed.row_no
)
UPDATE skill_nodes node
SET
    connect_to = connect_node.node_id,
    child_node_of = parent_node.node_id
FROM inserted_nodes seed
LEFT JOIN reference_nodes connect_node
    ON connect_node.career_name = seed.career_name
   AND connect_node.node_name = seed.connect_to_name
LEFT JOIN reference_nodes parent_node
    ON parent_node.career_name = seed.career_name
   AND parent_node.node_name = seed.child_node_of_name
WHERE node.node_id = seed.node_id;

COMMIT;
